import { useState } from 'react';
import { X, Loader2, MapPin, CheckCircle } from 'lucide-react';
import api from '../../lib/axios';

export const OrderModal = ({ item, onClose }) => {
  const [quantity, setQuantity] = useState(1);
  const [deliveryLocation, setDeliveryLocation] = useState('');
  const [paymentMethod, setPaymentMethod] = useState('Cash on Delivery');
  
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);

  const totalAmount = (quantity * item.pricePerKg).toFixed(2);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      await api.post('/orders', {
        produceId: item._id,
        quantityKg: Number(quantity),
        deliveryLocation,
        paymentMethod
      });
      setIsSuccess(true);
      // Wait 2 seconds so the user can see the success message, then close
      setTimeout(() => {
        onClose();
      }, 2000);
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to place order.');
    } finally {
      setIsLoading(false);
    }
  };

  if (isSuccess) {
    return (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
        <div className="bg-white rounded-2xl p-8 max-w-sm w-full text-center shadow-2xl">
          <CheckCircle className="mx-auto text-farmGreen mb-4" size={64} />
          <h3 className="text-2xl font-bold text-gray-900 mb-2">Order Confirmed!</h3>
          <p className="text-gray-500">Your request has been sent to the farmer.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 backdrop-blur-sm">
      <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
        
        {/* Header */}
        <div className="px-6 py-4 border-b border-gray-100 flex items-center justify-between bg-gray-50">
          <h3 className="text-lg font-bold text-gray-900">Purchase {item.cropType}</h3>
          <button onClick={onClose} className="p-1 text-gray-400 hover:text-gray-600 rounded-full hover:bg-gray-200 transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Form Body */}
        <div className="p-6 overflow-y-auto custom-scrollbar">
          {error && (
            <div className="mb-4 p-3 bg-red-50 text-red-700 text-sm font-medium rounded-lg border border-red-200">
              {error}
            </div>
          )}

          <div className="flex items-center gap-4 mb-6 p-4 bg-farmGreen-light/30 rounded-xl border border-farmGreen/20">
            <div className="flex-1">
              <p className="text-sm text-gray-500 font-medium">Available</p>
              <p className="text-lg font-bold text-gray-900">{item.weightKg} kg</p>
            </div>
            <div className="w-px h-10 bg-gray-200"></div>
            <div className="flex-1">
              <p className="text-sm text-gray-500 font-medium">Price per kg</p>
              <p className="text-lg font-bold text-gray-900">GHS {item.pricePerKg.toFixed(2)}</p>
            </div>
          </div>

          <form id="order-form" onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-bold text-gray-700 mb-1">Quantity (kg)</label>
              <input
                type="number"
                min="1"
                max={item.weightKg}
                required
                value={quantity}
                onChange={(e) => setQuantity(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-farmGreen/20 focus:border-farmGreen outline-none"
              />
            </div>

            <div>
              <label className="block text-sm font-bold text-gray-700 mb-1">Delivery Address</label>
              <div className="relative">
                <MapPin className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                <input
                  type="text"
                  required
                  placeholder="e.g. Accra Central, Market Square"
                  value={deliveryLocation}
                  onChange={(e) => setDeliveryLocation(e.target.value)}
                  className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-farmGreen/20 focus:border-farmGreen outline-none"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-bold text-gray-700 mb-1">Payment Method</label>
              <select
                value={paymentMethod}
                onChange={(e) => setPaymentMethod(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-white focus:ring-2 focus:ring-farmGreen/20 focus:border-farmGreen outline-none"
              >
                <option value="Cash on Delivery">Cash on Delivery</option>
                <option value="Manual Mobile Money">Manual Mobile Money</option>
              </select>
            </div>
          </form>
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-gray-100 bg-gray-50 flex items-center justify-between">
          <div>
            <p className="text-sm text-gray-500 font-medium">Total Price</p>
            <p className="text-2xl font-extrabold text-farmGreen">GHS {totalAmount}</p>
          </div>
          <button
            type="submit"
            form="order-form"
            disabled={isLoading || quantity > item.weightKg}
            className="px-6 py-2.5 bg-farmGreen hover:bg-farmGreen-dark text-white font-bold rounded-lg transition-colors flex items-center disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isLoading ? <><Loader2 className="animate-spin mr-2" size={18} /> Processing...</> : 'Place Order'}
          </button>
        </div>

      </div>
    </div>
  );
};
